
-- Customer Revenue Concentration Analysis
-- Identifying the number and percentage of customers responsible
-- for generating 80% of revenue within each territory.

-- Calculate total revenue generated by each customer within each territory
WITH CustomerRevenue AS (
    SELECT
        c.customerid,
        SUM(s.TOTALDUE) AS ClientRevenue,
        t.name AS TerritoryName
    FROM SALES.SalesOrderHeader S
    LEFT JOIN sales.Customer C
        ON c.customerid = s.customerid
    LEFT JOIN sales.SalesTerritory T
        ON t.TerritoryID = s.TerritoryID
    GROUP BY
        c.customerid,
        t.Name
),

-- Rank customers within each territory based on their revenue
RankedCustomers AS (
    SELECT
        TerritoryName,
        CustomerID,
        ClientRevenue,
        ROW_NUMBER() OVER (
            PARTITION BY TerritoryName
            ORDER BY ClientRevenue DESC
        ) AS ClientRank
    FROM CustomerRevenue
),

-- Calculate total revenue for each territory
TotalRevenueByTerritory AS (
    SELECT
        TerritoryName,
        SUM(ClientRevenue) AS TerritoryRevenue
    FROM CustomerRevenue
    GROUP BY TerritoryName
),

-- Calculate cumulative revenue based on customer ranking
RunningRevenue AS (
    SELECT
        rc.*,
        tr.TerritoryRevenue,
        SUM(rc.ClientRevenue) OVER (
            PARTITION BY rc.TerritoryName
            ORDER BY rc.ClientRank
        ) AS RunningRev
    FROM RankedCustomers rc
    LEFT JOIN TotalRevenueByTerritory tr
        ON tr.TerritoryName = rc.TerritoryName
),

-- Calculate the cumulative percentage of territory revenue
RevenuePercentage AS (
    SELECT
        *,
        (RunningRev * 100.00 / TerritoryRevenue) AS [RunningRevenue%]
    FROM RunningRevenue
),

-- Identify the minimum number of customers needed to reach at least 80% of territory revenue
Client80PctRevenue AS (
    SELECT
        TerritoryName,
        MIN(ClientRank) AS ClientsNeededFor80Pct
    FROM RevenuePercentage
    WHERE [RunningRevenue%] >= 80
    GROUP BY TerritoryName
),

-- Count the total number of customers in each territory
CustomerCountByTerritory AS (
    SELECT
        TerritoryName,
        COUNT(CustomerID) AS ClientCount
    FROM CustomerRevenue
    GROUP BY TerritoryName
)

-- Combine the results to evaluate revenue concentration across territories
SELECT
    TR.TerritoryName,
    TR.TerritoryRevenue,
    CT.ClientCount AS [Total Clients],
    C.ClientsNeededFor80Pct AS [Clients Required to Reach 80% Revenue],
    ROUND(
        C.ClientsNeededFor80Pct * 100.0 / CT.ClientCount,
        2
    ) AS [% Clients Required to Reach 80% Revenue]
FROM TotalRevenueByTerritory TR
LEFT JOIN Client80PctRevenue C
    ON C.TerritoryName = TR.TerritoryName
LEFT JOIN CustomerCountByTerritory CT
    ON CT.TerritoryName = TR.TerritoryName;
